code.source:
#include <stdio.h>

void swap(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
    printf("Inside swap: a = %d, b = %d\n", a, b);
}

int main(void) {
    int x = 5, y = 9;
    swap(x, y);
    printf("Back in main: x = %d, y = %d\n", x, y);
    return 0;
}

